     construct new() {
       this.material = "Warm Oak"
       this.seatMaterial = "Soft Gray Leather"
       this.backrestMaterial = "Deep Blue Leather"
       this.height = { seat: 18, backrest: 24 }
     }
   }

   class Bench {
     construct new() {
       this.material = "Solid Oak"
       this.finish = "Soft Gray"
       this.length = 8
       this.width = 3
     }
   }

   var bench = Bench.new()
   var chairs = [Chair.new(), Chair.new(), Chair.new(), Chair.new()]
