/* Basic styles */
.task-card {
    background-color: #f8f9fa;
    border-radius: 10px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    padding: 20px;
    position: relative;
    transition: transform 0.3s ease-in-out;
}

/* Responsive breakpoints */
@media (min-width: 320px) {
    .task-card { width: 95%; }
}
@media (min-width: 480px) {
    .task-card { width: 80%; }
}
@media (min-width: 768px) {
    .task-card { width: 60%; }
}
@media (min-width: 1024px) {
    .task-card { width: 50%; }
}
@media (min-width: 1280px) {
    .task-card { width: 30%; }
}

/* Hex color palette */
.task-card {
    --primary-color: #6c757d;
    --secondary-color: #28a745;
    --accent-color: #dc3545;
    --text-color: #212529;
    --background-color: #f8f9fa;
}

/* Animations */
@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}
@keyframes slideInLeft {
    from { transform: translateX(-100%); }
    to { transform: translateX(0); }
}
@keyframes bounce {
    0%, 20%, 50%, 80%, 100% { animation-timing-function: cubic-bezier(0.215, 0.61, 0.355, 1); }
    40% { transform: translate3d(-30px, 0, 0); }
    70% { transform: translate3d(15px, 0, 0); }
}

/* Icons */
.task-card .icon {
    fill: var(--text-color);
}
.icon-check { d: M12 2L2 22h20L12 2z; }
.icon-cancel { d: M4 9l7.5 7.5-1.41 1.41L3 16.41V4h16v12H3v-8.59L10.41 13.09z; }

/* Hover states */
.task-card:hover {
    transform: translateY(-5px);
}

/* Collaboration chip design */
.collaboration-chip {
    background-color: var(--accent-color);
    color: white;
    padding: 5px 10px;
    border-radius: 20px;
    font-size: 14px;
    margin-right: 5px;
}
```

